pub fn check_p61970_600_2_dynamics_ap_con_complex_inverseassociation_shacl_asynchronous_machine_asynchro_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut ref_counts: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    for src_mrid in dataset.by_type.get("AsynchronousMachineDynamics").into_iter().flatten() {
        if let Some(src) = dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::AsynchronousMachineDynamics>()) {
            if let Some(r) = &src.asynchronous_machine { *ref_counts.entry(r.mrid.as_str()).or_insert(0) += 1; }
        }
    }
    for src_mrid in dataset.by_type.get("AsynchronousMachineEquivalentCircuit").into_iter().flatten() {
        if let Some(src) = dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::AsynchronousMachineEquivalentCircuit>()) {
            if let Some(r) = &src.base.asynchronous_machine { *ref_counts.entry(r.mrid.as_str()).or_insert(0) += 1; }
        }
    }
    for src_mrid in dataset.by_type.get("AsynchronousMachineTimeConstantReactance").into_iter().flatten() {
        if let Some(src) = dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::AsynchronousMachineTimeConstantReactance>()) {
            if let Some(r) = &src.base.asynchronous_machine { *ref_counts.entry(r.mrid.as_str()).or_insert(0) += 1; }
        }
    }
    for src_mrid in dataset.by_type.get("AsynchronousMachineUserDefined").into_iter().flatten() {
        if let Some(src) = dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::AsynchronousMachineUserDefined>()) {
            if let Some(r) = &src.base.asynchronous_machine { *ref_counts.entry(r.mrid.as_str()).or_insert(0) += 1; }
        }
    }
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("AsynchronousMachine").into_iter().flatten() {
        let count = ref_counts.get(mrid.as_str()).copied().unwrap_or(0);
        if count > 1 {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dyi:AsynchronousMachine.AsynchronousMachineDynamics-cardinality".to_string(),
                class:       "AsynchronousMachine".to_string(),
                property:    "AsynchronousMachine.AsynchronousMachineDynamics-cardinality".to_string(),
                message:     "Wrong number of associated instances.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "AsynchronousMachine.AsynchronousMachineDynamics-cardinality".to_string(),
                description: "This constraint validates the cardinality of the association at the inverse direction.".to_string(),
            });
        }
    }
    violations
}

